import * as React from 'react';
import CssBaseline from '@mui/material/CssBaseline';
import Divider from '@mui/material/Divider';
import AppAppBar from './components/AppAppBar';
import Hero from './components/Hero';
import LogoCollection from './components/LogoCollection';
import Highlights from './components/Highlights';
import Portfolio from './components/Portfolio';
import Features from './components/Features';
import Testimonials from './components/Testimonials';
import FAQ from './components/FAQ';
import Footer from './components/Footer';
import AppTheme from '../shared-theme/AppTheme';
import { AppBar, Toolbar, Box, Button } from '@mui/material';
import ZohoChat from './components/ZohoChat';

export default function MarketingPage(props) {
  const [useSkeuomorphic, setUseSkeuomorphic] = React.useState(true);

  const toggleTheme = () => {
    setUseSkeuomorphic(prev => !prev);
  };

  return (
    <AppTheme useSkeuomorphic={useSkeuomorphic}>
      <CssBaseline enableColorScheme />
      <AppAppBar>
        <Button 
          onClick={toggleTheme}
          sx={{ ml: 2 }}
        >
          {useSkeuomorphic ? 'Modern Theme' : 'Skeuomorphic Theme'}
        </Button>
      </AppAppBar>
      <Hero />
      <div>
        <LogoCollection />
        <Features />
        <Divider />
        <Highlights />
        <Divider />
        <Portfolio />
        <Divider />
        <FAQ />
        <Divider />
        <Footer />
        <ZohoChat />
      </div>
    </AppTheme>
  );
}
